#!/usr/bin/env python3
"""
Civilization 6 District Adjacency Bonus Optimizer
Finds optimal district placements to maximize adjacency bonuses.
"""

import sqlite3
import json
from typing import Dict, List, Tuple, Optional, Set

# District types available
DISTRICTS = [
    'CAMPUS',
    'HOLY_SITE',
    'THEATER_SQUARE',
    'COMMERCIAL_HUB',
    'HARBOR',
    'INDUSTRIAL_ZONE',
    'ENCAMPMENT',
    'ENTERTAINMENT_COMPLEX'
]


class Civ6Map:
    """Handles reading and querying Civ6 map data."""

    def __init__(self, map_path: str):
        self.conn = sqlite3.connect(map_path)
        self.conn.row_factory = sqlite3.Row
        self.width, self.height = self._get_dimensions()
        self.plots = self._load_plots()

    def _get_dimensions(self) -> Tuple[int, int]:
        cursor = self.conn.execute("SELECT Width, Height FROM Map")
        row = cursor.fetchone()
        return row['Width'], row['Height']

    def _load_plots(self) -> Dict[int, dict]:
        """Load all plot data into memory."""
        plots = {}

        cursor = self.conn.execute("""
            SELECT p.ID, p.TerrainType, p.IsImpassable, p.ContinentType
            FROM Plots p
        """)

        for row in cursor:
            plots[row['ID']] = {
                'id': row['ID'],
                'terrain': row['TerrainType'],
                'impassable': bool(row['IsImpassable']),
                'continent': row['ContinentType'],
                'feature': None,
                'resource': None,
                'rivers': []
            }

        # Add features
        cursor = self.conn.execute("SELECT ID, FeatureType FROM PlotFeatures")
        for row in cursor:
            if row['ID'] in plots:
                plots[row['ID']]['feature'] = row['FeatureType']

        # Add resources
        cursor = self.conn.execute("SELECT ID, ResourceType FROM PlotResources")
        for row in cursor:
            if row['ID'] in plots:
                plots[row['ID']]['resource'] = row['ResourceType']

        # Add rivers
        cursor = self.conn.execute("""
            SELECT ID, IsNEOfRiver, IsWOfRiver, IsNWOfRiver
            FROM PlotRivers
        """)
        for row in cursor:
            if row['ID'] in plots:
                rivers = []
                if row['IsNEOfRiver']:
                    rivers.append('NE')
                if row['IsWOfRiver']:
                    rivers.append('W')
                if row['IsNWOfRiver']:
                    rivers.append('NW')
                plots[row['ID']]['rivers'] = rivers

        return plots

    def plot_id(self, x: int, y: int) -> int:
        """Convert (x, y) to plot ID."""
        return y * self.width + x

    def plot_coords(self, plot_id: int) -> Tuple[int, int]:
        """Convert plot ID to (x, y)."""
        return plot_id % self.width, plot_id // self.width

    def get_plot(self, x: int, y: int) -> Optional[dict]:
        """Get plot data for coordinates."""
        if not (0 <= x < self.width and 0 <= y < self.height):
            return None
        return self.plots.get(self.plot_id(x, y))

    def is_valid_pos(self, x: int, y: int) -> bool:
        """Check if position is within map bounds."""
        return 0 <= x < self.width and 0 <= y < self.height


def get_hex_neighbors(x: int, y: int) -> List[Tuple[int, int]]:
    """Get all 6 hex neighbors using odd-q vertical layout."""
    if x % 2 == 0:  # Even column
        neighbors = [
            (x, y - 1),      # N
            (x + 1, y - 1),  # NE
            (x + 1, y),      # SE
            (x, y + 1),      # S
            (x - 1, y),      # SW
            (x - 1, y - 1),  # NW
        ]
    else:  # Odd column
        neighbors = [
            (x, y - 1),      # N
            (x + 1, y),      # NE
            (x + 1, y + 1),  # SE
            (x, y + 1),      # S
            (x - 1, y + 1),  # SW
            (x - 1, y),      # NW
        ]
    return neighbors


def hex_distance(x1: int, y1: int, x2: int, y2: int) -> int:
    """Calculate hex distance between two points."""
    # Convert to cube coordinates
    def to_cube(x, y):
        q = x
        r = y - (x - (x % 2)) // 2
        s = -q - r
        return q, r, s

    q1, r1, s1 = to_cube(x1, y1)
    q2, r2, s2 = to_cube(x2, y2)

    return (abs(q1 - q2) + abs(r1 - r2) + abs(s1 - s2)) // 2


def is_mountain(plot: dict) -> bool:
    """Check if plot is a mountain."""
    return plot and ('MOUNTAIN' in plot['terrain'] or plot['impassable'])


def is_water(plot: dict) -> bool:
    """Check if plot is water."""
    return plot and plot['terrain'] in ['TERRAIN_OCEAN', 'TERRAIN_COAST']


def is_coast(plot: dict) -> bool:
    """Check if plot is coastal water."""
    return plot and plot['terrain'] == 'TERRAIN_COAST'


def has_river(plot: dict) -> bool:
    """Check if plot has a river adjacent."""
    return plot and len(plot.get('rivers', [])) > 0


class DistrictOptimizer:
    """Optimizes district placement for maximum adjacency bonuses."""

    def __init__(self, map_data: Civ6Map, num_cities: int, population: int):
        self.map = map_data
        self.num_cities = num_cities
        self.population = population
        self.max_districts = (population + 2) // 3

    def can_place_district(self, x: int, y: int, district_type: str,
                          city_center: Tuple[int, int],
                          occupied: Set[Tuple[int, int]]) -> bool:
        """Check if a district can be placed at this location."""
        # Must be valid position
        if not self.map.is_valid_pos(x, y):
            return False

        # Can't be occupied
        if (x, y) in occupied:
            return False

        # Must be within city range (3 tiles)
        if hex_distance(x, y, city_center[0], city_center[1]) > 3:
            return False

        plot = self.map.get_plot(x, y)
        if not plot:
            return False

        # Can't build on mountains/impassable
        if is_mountain(plot):
            return False

        # Harbor must be on coast
        if district_type == 'HARBOR':
            if not is_coast(plot):
                return False
        else:
            # Other districts need land
            if is_water(plot):
                return False

        return True

    def calculate_campus_bonus(self, x: int, y: int,
                               placements: Dict[str, Tuple[int, int]],
                               city_center: Tuple[int, int]) -> float:
        """Calculate Campus adjacency bonus."""
        bonus = 0.0
        neighbors = get_hex_neighbors(x, y)

        for nx, ny in neighbors:
            plot = self.map.get_plot(nx, ny)
            if not plot:
                continue

            # Mountains: +1
            if is_mountain(plot):
                bonus += 1

            # Rainforest/Jungle: +0.5
            if plot['feature'] == 'FEATURE_JUNGLE':
                bonus += 0.5

            # Reef: +1
            if plot['feature'] == 'FEATURE_REEF':
                bonus += 1

            # Geothermal Fissure: +1
            if plot['feature'] == 'FEATURE_GEOTHERMAL_FISSURE':
                bonus += 1

            # Other districts (not city center): -0.5
            if (nx, ny) in placements.values() and (nx, ny) != city_center:
                bonus -= 0.5

        return bonus

    def calculate_holy_site_bonus(self, x: int, y: int,
                                  placements: Dict[str, Tuple[int, int]],
                                  city_center: Tuple[int, int]) -> float:
        """Calculate Holy Site adjacency bonus."""
        bonus = 0.0
        neighbors = get_hex_neighbors(x, y)

        for nx, ny in neighbors:
            plot = self.map.get_plot(nx, ny)
            if not plot:
                continue

            # Mountains: +1
            if is_mountain(plot):
                bonus += 1

            # Forest: +0.5
            if plot['feature'] == 'FEATURE_FOREST':
                bonus += 0.5

            # Reef: +1
            if plot['feature'] == 'FEATURE_REEF':
                bonus += 1

            # Geothermal Fissure: +1
            if plot['feature'] == 'FEATURE_GEOTHERMAL_FISSURE':
                bonus += 1

            # Other districts (not city center): -0.5
            if (nx, ny) in placements.values() and (nx, ny) != city_center:
                bonus -= 0.5

        return bonus

    def calculate_commercial_hub_bonus(self, x: int, y: int,
                                       placements: Dict[str, Tuple[int, int]],
                                       city_center: Tuple[int, int]) -> float:
        """Calculate Commercial Hub adjacency bonus."""
        bonus = 0.0
        plot = self.map.get_plot(x, y)

        # River: +2
        if has_river(plot):
            bonus += 2

        neighbors = get_hex_neighbors(x, y)
        for nx, ny in neighbors:
            # Harbor: +2
            if placements.get('HARBOR') == (nx, ny):
                bonus += 2

            # Other districts (not city center or harbor): -0.5
            nplot = self.map.get_plot(nx, ny)
            if (nx, ny) in placements.values() and (nx, ny) != city_center:
                if placements.get('HARBOR') != (nx, ny):
                    bonus -= 0.5

        return bonus

    def calculate_harbor_bonus(self, x: int, y: int,
                              placements: Dict[str, Tuple[int, int]],
                              city_center: Tuple[int, int]) -> float:
        """Calculate Harbor adjacency bonus."""
        bonus = 0.0
        neighbors = get_hex_neighbors(x, y)

        for nx, ny in neighbors:
            # City Center: +2
            if (nx, ny) == city_center:
                bonus += 2

            # Commercial Hub: +2
            if placements.get('COMMERCIAL_HUB') == (nx, ny):
                bonus += 2

            plot = self.map.get_plot(nx, ny)
            if not plot:
                continue

            # Coast tiles: +0.5
            if is_coast(plot):
                bonus += 0.5

            # Sea resources: +1
            if plot['resource'] and is_water(plot):
                bonus += 1

            # Other districts: -0.5
            if (nx, ny) in placements.values() and (nx, ny) != city_center:
                if placements.get('COMMERCIAL_HUB') != (nx, ny):
                    bonus -= 0.5

        return bonus

    def calculate_industrial_zone_bonus(self, x: int, y: int,
                                        placements: Dict[str, Tuple[int, int]],
                                        city_center: Tuple[int, int]) -> float:
        """Calculate Industrial Zone adjacency bonus."""
        bonus = 0.0
        neighbors = get_hex_neighbors(x, y)

        for nx, ny in neighbors:
            plot = self.map.get_plot(nx, ny)
            if not plot:
                continue

            # Strategic resources: +1
            # (We don't have resource data, so skip this)

            # Mines/Quarries: +0.5
            # (We don't have improvement data in this scenario)

            # Other districts: -0.5 (except special)
            if (nx, ny) in placements.values() and (nx, ny) != city_center:
                bonus -= 0.5

        return bonus

    def calculate_theater_square_bonus(self, x: int, y: int,
                                       placements: Dict[str, Tuple[int, int]],
                                       city_center: Tuple[int, int]) -> float:
        """Calculate Theater Square adjacency bonus."""
        bonus = 0.0
        neighbors = get_hex_neighbors(x, y)

        for nx, ny in neighbors:
            # Entertainment Complex: +1
            if placements.get('ENTERTAINMENT_COMPLEX') == (nx, ny):
                bonus += 1

            # Other districts: -0.5
            if (nx, ny) in placements.values() and (nx, ny) != city_center:
                if placements.get('ENTERTAINMENT_COMPLEX') != (nx, ny):
                    bonus -= 0.5

        return bonus

    def calculate_adjacency(self, district: str, x: int, y: int,
                           placements: Dict[str, Tuple[int, int]],
                           city_center: Tuple[int, int]) -> float:
        """Calculate adjacency bonus for any district type."""
        if district == 'CAMPUS':
            return self.calculate_campus_bonus(x, y, placements, city_center)
        elif district == 'HOLY_SITE':
            return self.calculate_holy_site_bonus(x, y, placements, city_center)
        elif district == 'COMMERCIAL_HUB':
            return self.calculate_commercial_hub_bonus(x, y, placements, city_center)
        elif district == 'HARBOR':
            return self.calculate_harbor_bonus(x, y, placements, city_center)
        elif district == 'INDUSTRIAL_ZONE':
            return self.calculate_industrial_zone_bonus(x, y, placements, city_center)
        elif district == 'THEATER_SQUARE':
            return self.calculate_theater_square_bonus(x, y, placements, city_center)
        else:
            return 0.0

    def find_best_city_center(self) -> Tuple[int, int]:
        """Find the best location for city center."""
        # Look for land tiles near mountains and features
        best_score = -999999
        best_pos = None

        for plot_id, plot in self.map.plots.items():
            if is_water(plot) or is_mountain(plot):
                continue

            x, y = self.map.plot_coords(plot_id)
            score = 0

            # Count nearby mountains (good for Campus/Holy Site)
            neighbors = get_hex_neighbors(x, y)
            for nx, ny in neighbors:
                nplot = self.map.get_plot(nx, ny)
                if nplot:
                    if is_mountain(nplot):
                        score += 10
                    if nplot['feature'] == 'FEATURE_FOREST':
                        score += 2
                    if nplot['feature'] == 'FEATURE_JUNGLE':
                        score += 2
                    if has_river(nplot):
                        score += 5

            if score > best_score:
                best_score = score
                best_pos = (x, y)

        return best_pos if best_pos else (self.map.width // 2, self.map.height // 2)

    def optimize(self) -> dict:
        """Find optimal district placements."""
        # For single city scenario
        city_center = self.find_best_city_center()
        print(f"City center at: {city_center}")

        # Try different district combinations
        best_solution = None
        best_total = -999999

        # Priority districts to try
        priority_districts = ['CAMPUS', 'HOLY_SITE', 'COMMERCIAL_HUB', 'HARBOR', 'INDUSTRIAL_ZONE']

        # Get workable tiles
        workable = []
        for dx in range(-3, 4):
            for dy in range(-3, 4):
                x = city_center[0] + dx
                y = city_center[1] + dy
                if hex_distance(city_center[0], city_center[1], x, y) <= 3:
                    if self.map.is_valid_pos(x, y):
                        workable.append((x, y))

        # Greedy approach: build districts one at a time
        for num_districts in range(1, min(self.max_districts + 1, len(priority_districts) + 1)):
            placements = {}
            adjacency_bonuses = {}
            occupied = {city_center}

            for _ in range(num_districts):
                best_district = None
                best_pos = None
                best_bonus = -999999

                # Try each district type not yet placed
                for district in priority_districts:
                    if district in placements:
                        continue

                    # Try each valid position
                    for pos in workable:
                        if not self.can_place_district(pos[0], pos[1], district,
                                                      city_center, occupied):
                            continue

                        bonus = self.calculate_adjacency(district, pos[0], pos[1],
                                                        placements, city_center)

                        if bonus > best_bonus:
                            best_bonus = bonus
                            best_district = district
                            best_pos = pos

                if best_district:
                    placements[best_district] = best_pos
                    adjacency_bonuses[best_district] = best_bonus
                    occupied.add(best_pos)

            total = sum(adjacency_bonuses.values())
            if total > best_total:
                best_total = total
                best_solution = {
                    'placements': placements,
                    'adjacency_bonuses': adjacency_bonuses,
                    'total': total
                }

        return {
            'city_center': list(city_center),
            'placements': {k: list(v) for k, v in best_solution['placements'].items()},
            'adjacency_bonuses': best_solution['adjacency_bonuses'],
            'total_adjacency': best_solution['total']
        }


def main():
    # Read scenario
    with open('/data/scenario_3/scenario.json', 'r') as f:
        scenario = json.load(f)

    map_path = f"/data/{scenario['map_file']}"
    num_cities = scenario['num_cities']
    population = scenario['population']

    print(f"Scenario: {scenario['description']}")
    print(f"Map: {map_path}")
    print(f"Cities: {num_cities}, Population: {population}")

    # Load map
    map_data = Civ6Map(map_path)
    print(f"Map size: {map_data.width}x{map_data.height}")

    # Optimize
    optimizer = DistrictOptimizer(map_data, num_cities, population)
    solution = optimizer.optimize()

    print(f"\nSolution:")
    print(f"City Center: {solution['city_center']}")
    print(f"Districts: {len(solution['placements'])}")
    for district, pos in solution['placements'].items():
        bonus = solution['adjacency_bonuses'][district]
        print(f"  {district}: {pos} (bonus: {bonus})")
    print(f"Total Adjacency: {solution['total_adjacency']}")

    # Write output
    with open('/output/scenario_3.json', 'w') as f:
        json.dump(solution, f, indent=2)

    print("\nSolution written to /output/scenario_3.json")


if __name__ == '__main__':
    main()

