def get_hex_neighbors(x, y):
    if x % 2 == 0:
        return [(x, y - 1), (x + 1, y - 1), (x + 1, y), (x, y + 1), (x - 1, y), (x - 1, y - 1)]
    else:
        return [(x, y - 1), (x + 1, y), (x + 1, y + 1), (x, y + 1), (x - 1, y + 1), (x - 1, y)]

def hex_distance(x1, y1, x2, y2):
    def to_cube(x, y):
        q = x
        r = y - (x - (x % 2)) // 2
        return x, y - (x - (x % 2)) // 2, -x - (y - (x - (x % 2)) // 2)
    q1, r1, s1 = to_cube(x1, y1)
    q2, r2, s2 = to_cube(x2, y2)
    return (abs(q1 - q2) + abs(r1 - r2) + abs(s1 - s2)) // 2

